#!/usr/bin/env python3
"""Inventarul ecranelor ZK ale pluginului com.eva.ro.contab (planul de pornire §6a) — DOAR CITIRE pe cod.

Pentru fiecare formă (clasă care derivă, direct sau prin altă formă, din ADForm / WEvaFormBase / WSagaCrudForm):
titlul, numele din meniu (EvaMetadata), baza, câmpurile (etichetele «…:», coloanele grilei), butoanele (etichetele),
procesele chemate (Value «EVA_…» / clasele com.eva.ro.contab.process|banca|anaf|pornire) și dacă ajutorul există
(texte ajutor/res/help/<Ecran>.tsv, capitol în ManualEvA, captură ajutor/res/img/<Ecran>/).

Ieșiri: Documentatie/help/00_INVENTAR_ECRANE.md și idempiere/plugins/com.eva.ro.contab/test/fixtures/help/ecrane.tsv
(lista pentru TestAjutor). Rulare: python3 tools/help/inventar_ecrane.py (din rădăcina repo-ului).

P01.T240 (D-240-E1): ecrane.tsv e citit de 14 clase de test cu rândul exact, deci NU se rescrie: rândurile existente
(coloanele clasa / titlu / baza), comentariile și ordinea se păstrează byte cu byte; coloana 4 (buton «Ajutor») e un
fapt calculat din cod și se recalculează; ecranele noi se adaugă la coadă, în ordine alfabetică. Clasele abstracte
nu intră (detectorul ia cuvântul «abstract» din declarația clasei). Titlul unui rând NOU, în ordine: meniul din
EvaMetadata (literal, Etichete.t("…") sau ensureForm(…) pe mai multe linii, cu prefixul local String E = "…" și
clasa dată printr-o constantă), apoi titlu() din clasă (literal sau Etichete.t("…")); prefixul «EvA — » se scoate.
"""
import os
import re
import sys

RAD = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
SRC = os.path.join(RAD, "idempiere/plugins/com.eva.ro.contab/src/com/eva/ro/contab")
FORM = os.path.join(SRC, "form")
BAZE = {"ADForm", "WEvaFormBase", "WSagaCrudForm"}
CU_BUTON_AJUTOR = {"WEvaFormBase", "WSagaCrudForm"}   # bazele care pun butonul «Ajutor» automat


def citeste(p):
    with open(p, encoding="utf-8") as f:
        return f.read()


def fara_comentarii(s):
    """Sursa Java fără comentarii `//` și `/* */`, sărind literalii șir / caracter / bloc de text (un «http://…» dintr-un șir
    rămâne întreg). P01.T240 01c-3 (D-240-34, CO-12): aceeași regulă ca `TestAjutor.faraComentariiT240`."""
    o, i, n = [], 0, len(s)
    while i < n:
        c = s[i]
        if s.startswith('"""', i):
            e = s.find('"""', i + 3)
            e = n if e < 0 else e + 3
            o.append(s[i:e]); i = e
        elif c in "\"'":
            j = i + 1
            while j < n and s[j] != c and s[j] != "\n":
                j += 2 if s[j] == "\\" else 1
            j = min(j + 1, n)
            o.append(s[i:j]); i = j
        elif s.startswith("//", i):
            e = s.find("\n", i)
            i = n if e < 0 else e
        elif s.startswith("/*", i):
            e = s.find("*/", i + 2)
            i = n if e < 0 else e + 2
            o.append(" ")
        else:
            o.append(c); i += 1
    return "".join(o)


# P01.T240 RR LR-1 (D-240-76): detectorul claselor-ecran, IDENTIC cu `TestAjutor.claseFormT240` (testul de egalitate:
# tools/teste/t240/test_clasa_detector_lr1.py). (a) orice modificatori, în orice ordine, înaintea lui «class»; parametrii
# generici înaintea lui «extends»; (b) baza calificată «x.y.Z» ⇒ ultimul segment «Z»; (c) toate subdosarele lui form/,
# recursiv, mai puțin cele din EXCLUDERI_FORM (relativ la form/, fiecare cu motivul); (d) comentariile și conținutul
# literalilor (șir, caracter, bloc de text) nu se citesc; toate declarațiile din fișier (și cele interioare), nu doar prima.
# RR LR-2 (D-240-84): identificatorii Java după JLS §3.8 — litere Unicode (diacritice), cifre, «_» și «$»: `\w` din `re` pe `str`
# e Unicode, iar Java compilează aceeași expresie cu Pattern.UNICODE_CHARACTER_CLASS; adnotările printre modificatori
# («public abstract @Deprecated class») nu pierd «abstract». O clasă imbricată se vede cu numele ei simplu (`Inner`), nu cu
# numele binar `Outer$Inner` (acela nu apare în sursă); un nume scris cu «$» în sursă (`W$X`) e o clasă legală și se vede.
DECL_CLASA = (r"\b((?:(?:public|protected|private|abstract|final|static|strictfp|sealed|non-sealed)\s+|@[\w$.]+(?:\s*\([^)]*\))?\s+)*)"
              r"class\s+([\w$]+)(?:\s*<[^{]*?>)?\s+extends\s+([\w$.]+)")
SIRURI = r'"""[\s\S]*?"""|"(?:[^"\\\n]|\\.)*"|' + r"'(?:[^'\\\n]|\\.)*'"
EXCLUDERI_FORM = {}   # niciun subdosar exclus: form/reges/res are doar resurse (.tsv), fără .java; o excludere nouă = rând «dosar: motiv»


def fara_siruri(s):
    """P01.T240 RR LR-1 (d): literalii șir / caracter / bloc de text goliți («"…"» → «""»); se aplică după `fara_comentarii`."""
    return re.sub(SIRURI, lambda m: m.group(0)[0] * (6 if m.group(0).startswith('"""') else 2), s)


def declaratii(s):
    """P01.T240 RR LR-1: [(nume, baza = ultimul segment, abstract)] pentru fiecare declarație «… class N … extends B» din sursa Java `s`."""
    return [(m.group(2), m.group(3).split(".")[-1], "abstract" in m.group(1).split())
            for m in re.finditer(DECL_CLASA, fara_siruri(fara_comentarii(s)))]


def fisiere_form(form=None):
    """P01.T240 RR LR-1 (c): căile relative la form/ ale tuturor fișierelor .java din form/**, sortate, fără dosarele din EXCLUDERI_FORM."""
    form = form or FORM
    out = []
    for d, sub, fis in os.walk(form):
        rel = os.path.relpath(d, form).replace(os.sep, "/")
        sub[:] = [x for x in sub if (x if rel == "." else rel + "/" + x) not in EXCLUDERI_FORM]
        out += [n if rel == "." else rel + "/" + n for n in fis if n.endswith(".java")]
    return sorted(out)


def clase(form=None):
    form = form or FORM
    out = {}
    for r in fisiere_form(form):
        p = os.path.join(form, r)
        s = citeste(p)
        for nume, baza, abstr in declaratii(s):
            out[nume] = {"baza": baza, "src": s, "cale": os.path.relpath(p, RAD), "abstract": abstr}   # P01.T240 (CO-4): «abstract» din declarație
    return out


def lant(c, cl):
    l = []
    while c in cl:
        l.append(cl[c]["baza"])
        c = cl[c]["baza"]
    return l


def meniu():
    s = citeste(os.path.join(SRC, "setup/EvaMetadata.java"))
    m = {}
    for nume, cls in re.findall(r'\{"([^"]+)",\s*"(W\w+Form)",\s*"\d+"\}', s):
        m.setdefault(cls, nume)
    for nume, cls in re.findall(r'ensureForm\([^"]*"EvA — ([^"]+)",\s*"com\.eva\.ro\.contab\.form\.(\w+)"', s):
        m.setdefault(cls, nume)
    return m


SIR = r'"((?:[^"\\]|\\.)*)"'
ETI_T = r'(?:[\w.]*\.)?Etichete\.t\(\s*'


def text_expr(expr, prefixe):
    """P01.T240: textul unei expresii Java din literale și Etichete.t("k") / Etichete.t(E + "k") (E = prefixul local); None dacă nu se poate."""
    global ETI
    if ETI is None:
        ETI = etichete_ro()
    out = ""
    rest = expr.strip()
    while rest:
        m = re.match(r'%s\s*' % SIR, rest)
        if m:
            out += m.group(1)
        else:
            m = re.match(r'%s(?:(\w+)\s*\+\s*)?%s\s*\)\s*' % (ETI_T, SIR), rest)
            if not m:
                return None
            k = prefixe.get(m.group(1), None) if m.group(1) else ""
            if k is None or (k + m.group(2)) not in ETI:
                return None
            out += ETI[k + m.group(2)]
        rest = rest[m.end():].lstrip()
        if rest.startswith("+"):
            rest = rest[1:].lstrip()
        elif rest:
            return None
    return out or None


def titluri_noi():
    """P01.T240 (CO-2): titlurile din EvaMetadata pe care meniu() nu le vede (Etichete.t, ensureForm pe mai multe linii)."""
    s = fara_comentarii(citeste(os.path.join(SRC, "setup/EvaMetadata.java")))
    constante = {}
    for r, _, fs in os.walk(SRC):
        for n in fs:
            if n.endswith(".java"):
                for nume, cls in re.findall(r'(\w+)\s*=\s*"com\.eva\.ro\.contab\.form\.(\w+)"', citeste(os.path.join(r, n))):
                    constante.setdefault(n[:-5] + "." + nume, cls)   # cheia Clasa.CONSTANTA (numele constantei se repetă între clase)
    m = {}
    for x in re.finditer(r'\{\s*(%s%s\s*\))\s*,\s*"(W\w+Form)"\s*,\s*"\d+"\s*\}' % (ETI_T, SIR), s):
        t = text_expr(x.group(1), {})
        if t:
            m.setdefault(x.group(3), t)
    for c in re.finditer(r'ensureForm\(\s*\w+\s*,\s*\w+\s*,\s*\w+\s*,\s*(.+?)\s*,\s*("com\.eva\.ro\.contab\.form\.(\w+)"|[\w.]*?(\w+\.\w+))\s*\)\s*;', s, re.S):
        cls = c.group(3) or constante.get(c.group(4))
        if not cls:
            continue
        prefixe = {}
        for p in re.finditer(r'String\s+(\w+)\s*=\s*%s\s*;' % SIR, s[:c.start()]):
            prefixe[p.group(1)] = p.group(2)
        t = text_expr(c.group(1), prefixe)
        if t:
            m.setdefault(cls, t[len("EvA — "):] if t.startswith("EvA — ") else t)
    return m


def titlu_clasa(info):
    """P01.T240: titlu() din clasă — literal sau Etichete.t("k")."""
    s = fara_comentarii(info["src"])
    t = re.search(r'titlu\(\)\s*\{\s*return\s+([^;]+);', s)
    return text_expr(t.group(1), {}) if t else None


def argumente_apel(s, i):
    """Textul dintre parantezele apelului care începe la s[i] == '(' (paranteze echilibrate, literalii săriți)."""
    d, j, n = 0, i, len(s)
    while j < n:
        c = s[j]
        if c == '"':
            j += 1
            while j < n and s[j] != '"':
                j += 2 if s[j] == "\\" else 1
        elif c == "(":
            d += 1
        elif c == ")":
            d -= 1
            if d == 0:
                return s[i + 1:j]
        j += 1
    return s[i + 1:]


def capitole():
    """Clasele cu capitol în ManualEvA / ManualReges. P01.T240 tranșa 16 (D-240-55): și capitolele cu titlul din
    Etichete.t(…) — al treilea argument al lui cap(…) se ia din apelul întreg (paranteze echilibrate), nu din «"…", "…",»."""
    s = fara_comentarii(citeste(os.path.join(SRC, "ajutor/ManualEvA.java")))
    s += fara_comentarii(citeste(os.path.join(SRC, "ajutor/ManualReges.java")))
    out = set(re.findall(r'FORMA = "(W\w+Form)"', s))
    for m in re.finditer(r'(?<![\w.])cap\s*\(', s):
        arg = argumente_apel(s, m.end() - 1)
        f = re.search(r'"(W\w+Form)"', arg)
        if f:
            out.add(f.group(1))
    return out


def unic(l):
    v = []
    for x in l:
        x = x.strip()
        if x and x not in v:
            v.append(x)
    return v


def etichete_ro():
    """cheie -> text ro din etichete.tsv (D7: butoanele construite cu Etichete.t(...)). P01.T240 tranșa 16: și
    form/reges/res/etichete.tsv (EticheteReges), după cel comun (cheia comună are prioritate)."""
    m = {}
    for f in ("documente/res/etichete.tsv", "form/reges/res/etichete.tsv"):
        for l in citeste(os.path.join(SRC, f)).split("\n"):
            c = l.split("\t")
            if len(c) >= 2 and not l.startswith("#"):
                m.setdefault(c[0], c[1])
    return m


CHEIE = re.compile(r'^[a-z][a-z0-9_]*(?:\.[a-z0-9_]+)+$')    # o cheie de etichetă scrisă ca literal («compsaga.col.luna»)
LATIME = re.compile(r'^\d+(?:px|%)$')                        # o lățime de coloană («50px»), nu un titlu
TIP_BUTON = r'(?:[\w.]*\.)?(?:Button|Checkbox|Toolbarbutton|Radio|Menuitem|Combobutton)'


def prefixe_chei(s):
    """Prefixele cu care sursa compune cheile: Etichete.t("t21.iesf." + cod) → «t21.iesf.»."""
    return sorted(set(re.findall(r'Etichete\.t\(\s*"([a-z0-9_.]+\.)"\s*\+', s)))


def rezolva(x, prefixe):
    """P01.T240 tranșa 16 (D-240-50/68): un literal care e o CHEIE de etichetă → textul ro (direct sau cu un prefix al
    sursei); None = cheie nerezolvată (raportată, nu ascunsă); orice alt text rămâne cum e."""
    global ETI
    if ETI is None:
        ETI = etichete_ro()
    if not CHEIE.match(x):
        return x
    if x in ETI:
        return ETI[x]
    for p in prefixe:
        if p + x in ETI:
            return ETI[p + x]
    return None


def variabile_buton(s):
    """Numele variabilelor / câmpurilor declarate cu un tip de buton (Button, Checkbox …) — receptorii valizi ai setLabel."""
    return set(re.findall(r'\b%s\s+(\w+)\s*[=;:,)]' % TIP_BUTON, s))


def valoare_bool(metoda, clasa, cl):
    """`boolean metoda() { return true|false; }` pe clasă sau pe prima bază care o declară; None dacă nu e trivială."""
    for c in [clasa] + lant(clasa, cl):
        if c in cl:
            m = re.search(r'boolean\s+%s\s*\(\s*\)\s*\{\s*return\s+(true|false)\s*;\s*\}' % re.escape(metoda),
                          fara_comentarii(cl[c]["src"]))
            if m:
                return m.group(1) == "true"
    return None


ETI = None
AJUTATOARE = ("DialogReinchidere", "DocumenteButon", "BandaDeclaratie", "DialogDeconturiDepuse", "JobFundal",
              "TiparireButon")   # P01.T240 tranșa 16: «Tiparire» pus pe bară de TiparireButon.ataseaza


def butoane_eticheta(s, tipuri=None):
    """Butoanele cu Button(Etichete.t("cheie")) -> textul ro al cheii. P01.T240 tranșa 16 (D-240-68): setLabel doar pe un
    receptor declarat buton (`tipuri`; implicit cele din `s`) — «c.setLabel(…)» pe o celulă (Listcell) nu e buton."""
    global ETI
    if ETI is None:
        ETI = etichete_ro()
    tipuri = variabile_buton(s) if tipuri is None else tipuri
    ch = re.findall(r'Button\(\s*(?:[\w.]*\.)?Etichete\.t\(\s*"([^"]+)"', s)          # new Button(Etichete.t("k")), și calificat
    ch += [k for r, k in re.findall(r'(\w+)\.setLabel\(\s*(?:[\w.]*\.)?Etichete\.t\(\s*"([^"]+)"', s)
           if r in tipuri]                                                                # btX.setLabel(Etichete.t("k"))
    ch += re.findall(r'\bbuton\(\s*\w+\s*,\s*"([^"]+)"', s)                           # buton(btX, "decl.btn.xml", ...) din BandaDeclaratie
    return [ETI[k] for k in ch if k in ETI]


def corpuri_statice(s):
    """{metodă statică: corpul ei (supraîncărcările lipite)} — pentru atribuirea butoanelor unei clase ajutătoare."""
    out = {}
    for m in re.finditer(r'\bstatic\s+(?:<[^>]*>\s*)?[\w.<>\[\], ?]+?\s+(\w+)\s*\(', s):
        i = s.find("{", m.end())
        j = s.find(";", m.end())
        if i < 0 or (0 <= j < i and ")" in s[m.end():j] and "{" not in s[m.end():j]):
            continue   # declarație fără corp
        d, k = 0, i
        while k < len(s):
            if s[k] == "{":
                d += 1
            elif s[k] == "}":
                d -= 1
                if d == 0:
                    break
            k += 1
        out[m.group(1)] = out.get(m.group(1), "") + s[i:k + 1]
    return out


AJ_CACHE = {}


def butoane_ajutatoare(aj, s):
    """P01.T240 tranșa 16 (D-240-57/68): butoanele clasei ajutătoare `aj` pe care forma (sursa `s`) le pune pe ecran:
    `new Aj(` → toate; altfel doar ale metodelor statice CHEMATE (`Aj.m(`), cu închiderea tranzitivă pe apelurile interne
    (DocumenteButon.ataseaza → creeaza → deschide); `Aj.radacina(` / `JobFundal.mesaj(` nu aduc butoane."""
    ps = os.path.join(FORM, aj + ".java")
    if not os.path.isfile(ps):
        return []
    if aj not in AJ_CACHE:
        src = fara_comentarii(citeste(ps))
        AJ_CACHE[aj] = (src, corpuri_statice(src), variabile_buton(src))
    src, corp, tip = AJ_CACHE[aj]
    if re.search(r'\bnew\s+%s\s*\(' % aj, s):
        return butoane_eticheta(src, tip)
    vazute, stiva = set(), [x for x in re.findall(r'\b%s\.(\w+)\s*\(' % aj, s) if x in corp]
    while stiva:
        x = stiva.pop()
        if x in vazute:
            continue
        vazute.add(x)
        stiva += [y for y in corp if y not in vazute and re.search(r'(?<![\w.])%s\s*\(' % y, corp[x])]
    out = []
    for x in sorted(vazute):
        out += butoane_eticheta(corp[x], tip)
    return out


def eticheta_arg(a, prefixe):
    """Textul unui argument de etichetă: literal sau Etichete.t("k"); None dacă nu se poate citi."""
    a = a.strip()
    m = re.fullmatch(r'"([^"]*)"', a)
    if m:
        return rezolva(m.group(1), prefixe)
    m = re.fullmatch(r'(?:[\w.]*\.)?Etichete\.t\(\s*"([^"]+)"\s*\)', a)
    return ETI.get(m.group(1)) if m and ETI is not None else None


def butoane_moarte(nume, s, cl, prefixe):
    """P01.T240 tranșa 16 (D-240-68): etichetele care NU apar pe ecranul clasei `nume`:
    (1) butoanele doar din ramura moartă a lui `m() ? new Button[]{…} : new Button[]{…}` (m trivial true / false pe clasă —
    Ieșiri vs Intrări); (2) eticheta din constructor înlocuită de `if (m()) btX.setLabel(…)` cu m adevărată («Document nou»
    → «Adaug»), respectiv eticheta din setLabel când m e falsă."""
    global ETI
    if ETI is None:
        ETI = etichete_ro()
    ctor = {}
    for m in re.finditer(r'\b(\w+)\s*=\s*new\s+%s\s*\(' % TIP_BUTON, s):
        t = eticheta_arg(argumente_apel(s, m.end() - 1), prefixe)
        if t:
            ctor[m.group(1)] = t
    mort = []
    for m in re.finditer(r'\b(\w+)\s*\(\s*\)\s*\?\s*new\s+%s\s*\[\]\s*\{([^}]*)\}\s*:\s*new\s+%s\s*\[\]\s*\{([^}]*)\}'
                         % (TIP_BUTON, TIP_BUTON), s):
        v = valoare_bool(m.group(1), nume, cl)
        if v is None:
            continue
        viu, nevazut = (m.group(2), m.group(3)) if v else (m.group(3), m.group(2))
        vii = set(re.findall(r'\w+', viu))
        mort += [ctor[x] for x in re.findall(r'\w+', nevazut) if x not in vii and x in ctor]
    for m in re.finditer(r'\bif\s*\(\s*(\w+)\s*\(\s*\)\s*\)\s*(\w+)\.setLabel\s*\(', s):
        v = valoare_bool(m.group(1), nume, cl)
        if v is None:
            continue
        if v and m.group(2) in ctor:
            mort.append(ctor[m.group(2)])
        elif not v:
            t = eticheta_arg(argumente_apel(s, m.end() - 1), prefixe)
            if t:
                mort.append(t)
    return mort


def analiza(nume, info, cl=None):
    s = fara_comentarii(info["src"])
    cl = cl if cl is not None else CLASE()
    prefixe = prefixe_chei(s + "".join(fara_comentarii(cl[c]["src"]) for c in lant(nume, cl) if c in cl))
    tip = variabile_buton(s)
    titlu = re.search(r'titlu\(\)\s*\{\s*return\s+"([^"]+)"', s)
    butoane = re.findall(r'new\s+(?:org\.adempiere\.webui\.component\.|org\.zkoss\.zul\.)?Button\(\s*"([^"]+)"', s)
    butoane += re.findall(r'\bbuton\(\s*"([^"]+)"', s)
    butoane += [x for r, x in re.findall(r'(\w+)\.setLabel\(\s*"([^"]+)"', s) if r in tip]   # tranșa 16: doar pe butoane
    butoane += butoane_eticheta(s, tip)
    for aj in AJUTATOARE:       # D7: butoanele claselor ajutătoare se atribuie formelor care le cheamă (tranșa 16: pe metodă)
        if re.search(r'\b%s\b' % aj, s):
            butoane += butoane_ajutatoare(aj, s)
    mort = butoane_moarte(nume, s, cl, prefixe)
    butoane = [x for x in butoane if x not in mort]
    campuri = [x for x in re.findall(r'new\s+(?:org\.adempiere\.webui\.component\.|org\.zkoss\.zul\.)?Label\(\s*"([^"]{2,60})"', s)
               if x.strip().endswith(":") or x.strip().endswith("▾")]
    coloane = [x for x in re.findall(r'\{\s*"([^"]{1,40})"\s*,\s*"\d+px"', s) if not LATIME.match(x.strip())]   # tranșa 16: «50px» nu e titlu
    nerezolvate = []
    for lista in (butoane, campuri, coloane):   # tranșa 16 (D-240-50): cheile scrise ca literal → textul lor
        for i, x in enumerate(lista):
            t = rezolva(x.strip(), prefixe)
            if t is None:
                nerezolvate.append(x)
            lista[i] = x if t is None else t
    procese = re.findall(r'"(EVA_[A-Z][A-Za-z0-9_]+)"', s)
    procese = [p for p in procese if not p.startswith("EVA_SAGA_") and not p.endswith("_ID")
               and re.search(r'(ruleaza|AD_Process|Value=|processIt|proces)', s)]
    procese = [p for p in procese if re.search(r'(ruleaza\(\s*"%s"|AD_Process[^;]*"%s"|"%s"\.equals|proces\w*\(\s*"%s")'
                                                 % ((re.escape(p),) * 4), s)]
    clase_proc = re.findall(r'com\.eva\.ro\.contab\.(?:process|banca|anaf|pornire)\.(\w+)', s)
    return {"titlu": titlu.group(1) if titlu else "", "butoane": unic([x for x in butoane if x not in nerezolvate]),
            "campuri": unic([x for x in campuri if x not in nerezolvate]),
            "coloane": unic([x for x in coloane if x not in nerezolvate]), "procese": unic(procese + clase_proc),
            "nerezolvate": unic(nerezolvate)}


_CL = None


def CLASE():
    global _CL
    if _CL is None:
        _CL = clase()
    return _CL


def main():
    cl = clase()
    men = meniu()
    caps = capitole()
    help_dir = os.path.join(SRC, "ajutor/res/help")
    img_dir = os.path.join(SRC, "ajutor/res/img")
    ecrane = []
    for n, info in cl.items():
        l = lant(n, cl)
        if not (BAZE & set(l)) or n in BAZE or info["abstract"]:
            continue
        a = analiza(n, info, cl)
        a.update({"clasa": n, "baza": info["baza"], "cale": info["cale"], "meniu": men.get(n, ""),
                  "buton_ajutor": bool(CU_BUTON_AJUTOR & set(l)) or any(
                      "AjutorEcran.buton(this)" in fara_comentarii(cl[x]["src"]) for x in [n] + l if x in cl)   # 01c-3: codul, nu comentariile
                      or "PanouAjutor.subiect(" in fara_comentarii(info["src"]),   # REGES (decizia 08x b): buton propriu, subiect + cuprins
                  "buton_propriu": "PanouAjutor.subiect(" in info["src"],
                  "tsv": os.path.isfile(os.path.join(help_dir, n + ".tsv")),
                  "manual": n in caps,
                  "captura": os.path.isfile(os.path.join(img_dir, n, n + ".png"))})
        ecrane.append(a)
    ecrane.sort(key=lambda e: e["clasa"])
    cu_help = sum(1 for e in ecrane if e["tsv"] or e["manual"])
    out = [
        "# Inventarul ecranelor ZK — pluginul com.eva.ro.contab",
        "",
        "> Generat de `tools/help/inventar_ecrane.py` (citire din cod, nu de mână). Nu edita: rulează scriptul din nou.",
        "",
        f"**{len(ecrane)} ecrane** · cu ajutor (texte `ajutor/res/help/<Ecran>.tsv` sau capitol în ManualEvA): **{cu_help}** · "
        f"fără ajutor: **{len(ecrane) - cu_help}** · cu buton «Ajutor» (automat pe WEvaFormBase / WSagaCrudForm sau pus explicit): "
        f"**{sum(1 for e in ecrane if e['buton_ajutor'])}** (din care cu buton propriu, excepție REGES: "
        + ", ".join("`%s`" % e["clasa"] for e in ecrane if e["buton_propriu"]) + f") · cu captură: **{sum(1 for e in ecrane if e['captura'])}**",
        "",
        "| Ecran (clasă) | Meniu | Baza | Câmpuri | Coloane | Butoane | Procese | Buton «Ajutor» | Texte | Manual |",
        "|---|---|---|---|---|---|---|---|---|---|",
    ]
    for e in ecrane:
        out.append("| `%s` | %s | %s | %d | %d | %d | %d | %s | %s | %s |" % (
            e["clasa"], e["meniu"] or e["titlu"] or "—", e["baza"], len(e["campuri"]), len(e["coloane"]),
            len(e["butoane"]), len(e["procese"]), "da" if e["buton_ajutor"] else "nu", "da" if e["tsv"] else "—",
            "da" if e["manual"] else "—"))
    out.append("")
    for e in ecrane:
        out += ["## %s — `%s`" % (e["meniu"] or e["titlu"] or e["clasa"], e["clasa"]), "",
                "- **Sursa:** `%s` (baza `%s`)" % (e["cale"], e["baza"])]
        if e["titlu"]:
            out.append("- **Titlu:** %s" % e["titlu"])
        out.append("- **Câmpuri:** " + (", ".join("«%s»" % x for x in e["campuri"]) or "—"))
        out.append("- **Coloanele grilei:** " + (", ".join("«%s»" % x for x in e["coloane"]) or "—"))
        out.append("- **Butoane:** " + (", ".join("«%s»" % x for x in e["butoane"]) or "—"))
        out.append("- **Procese chemate:** " + (", ".join("`%s`" % x for x in e["procese"]) or "—"))
        out.append("- **Ajutor:** buton automat %s · texte %s · capitol ManualEvA %s · captură %s" % (
            "da" if e["buton_ajutor"] else "nu", "da" if e["tsv"] else "nu", "da" if e["manual"] else "nu",
            "da" if e["captura"] else "nu"))
        out.append("")
    dest = os.path.join(RAD, "Documentatie/help")
    os.makedirs(dest, exist_ok=True)
    with open(os.path.join(dest, "00_INVENTAR_ECRANE.md"), "w", encoding="utf-8") as f:
        f.write("\n".join(out))
    fx = os.path.join(RAD, "idempiere/plugins/com.eva.ro.contab/test/fixtures/help")
    os.makedirs(fx, exist_ok=True)
    pe = os.path.join(fx, "ecrane.tsv")
    vechi = citeste(pe).split("\n") if os.path.isfile(pe) else ["# clasa\tmeniu_sau_titlu\tbaza\tbuton_ajutor"]
    if vechi and vechi[-1] == "":
        vechi = vechi[:-1]
    dupa = {e["clasa"]: e for e in ecrane}
    linii, avute = [], set()
    for l in vechi:   # P01.T240 (D-240-E1): rândurile existente păstrate; doar coloana 4 recalculată din cod
        c = l.split("\t")
        if not l.startswith("#") and len(c) == 4 and c[0] in dupa:
            avute.add(c[0])
            l = "\t".join(c[:3] + ["Y" if dupa[c[0]]["buton_ajutor"] else "N"])
        elif not l.startswith("#") and c:
            avute.add(c[0])
        linii.append(l)
    tn = titluri_noi()
    for e in ecrane:   # ecranele noi la coadă (ordinea alfabetică a listei)
        if e["clasa"] not in avute:
            t = e["meniu"] or tn.get(e["clasa"]) or e["titlu"] or titlu_clasa(cl[e["clasa"]]) or ""
            linii.append("%s\t%s\t%s\t%s" % (e["clasa"], t, e["baza"], "Y" if e["buton_ajutor"] else "N"))
    with open(pe, "w", encoding="utf-8") as f:
        f.write("\n".join(linii) + "\n")
    print("%d ecrane, %d cu ajutor, %d fără" % (len(ecrane), cu_help, len(ecrane) - cu_help))


if __name__ == "__main__":
    sys.exit(main())


