#!/usr/bin/env python3
"""Verificatorul tabelelor de help (T08, plan v2 §5): pentru fiecare ajutor/res/help/<Ecran>.tsv cere
Documentatie/help/verificare/<Ecran>.md cu exact rândurile-cheie ale .tsv-ului, fiecare cu dovadă și verdict.
DOAR CITIRE. Rulare (din rădăcina repo-ului): python3 -I tools/help/verifica_help.py [--en-diacritice] [--ro-formal] [--fara-tabel Ecran,...]

Ieșire: tabele X/Y · chei fără rând N · rânduri fără dovadă N · rânduri «plauzibil» N · ro formal N · en diacritice N · butoane fără rând N · câmpuri fără rând N
· inventar fără butoane N · chei nerezolvate N (P01.T240 tranșa 16: cheile scrise ca literal pe care inventarul nu le găsește în etichete)
Cod de ieșire 0 doar când X = Y (minus --fara-tabel) și toți contoarele sunt 0.
P01.T240 (L2): verifică și suplimentele ajutor/res/help/supliment/<E>.tsv față de verificare/supliment/<E>.md (contoarele
«supliment: tabele a/b · chei fără rând n · ro formal n · en diacritice n», adăugate la coada ultimei linii, intră în rc;
forma de politețe și diacriticele EN se verifică și pe suplimente — D-240-45).
P01.T240 (L4, C-10): --citari = fiecare apariție R-CIT (rânduri non-#, H/*.tsv + H/supliment/*.tsv) are rând în
Documentatie/help/00_CITARI_LEGALE.md legat de `fișier:rând` (CO-10), cu URL oficial (https, domeniile PT-T240-2), data citirii și
verdict. Ultima linie: «apariții A · distincte D · rânduri .tsv R · citări fără rând N · rânduri fără URL M · rânduri fără dată / verdict K
· rânduri fără apariție Z»; rc 0 doar cu N = M = K = Z = 0.
Format rând de tabel:  | cheie | afirmația ro | dovada (fișier:linie / URL) | verdict |   verdict = DA | CORECTAT: vechi → nou | ȘTERS | [de confirmat]
"""
import os
import re
import sys
import unicodedata

RAD = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
SRC = os.path.join(RAD, "idempiere/plugins/com.eva.ro.contab/src/com/eva/ro/contab")
HELP = os.path.join(SRC, "ajutor/res/help")
VER = os.path.join(RAD, "Documentatie/help/verificare")
VERDICT = re.compile(r"^(DA|CORECTAT:.+|ȘTERS|\[de confirmat\].*)$")
FORMAL = re.compile(r"dumneavoastră|dvs\.|apăsați|alegeți|introduceți|selectați"
                    r"|bifați|măriți|schimbați", re.I)   # P01.T240 L2 (D-240-45): formele de politețe găsite în supliment/
DIAC = re.compile(r"[ăâîșțĂÂÎȘȚ]")
CITAT = re.compile(r"«[^»]*»")
SUPL = os.path.join(HELP, "supliment")
VSUPL = os.path.join(VER, "supliment")
CITARI = os.path.join(RAD, "Documentatie/help/00_CITARI_LEGALE.md")
# R-CIT = exact celula C-10 a planului 03_ (forma lungă ∪ tiparul T08 §3.6 integral); «Ordine cronologică» nu e prinsă (X348)
R_CIT = re.compile(r"(HG|H\.G\.|OUG|O\.U\.G\.|OG|Legea|Legii|OMFP|OMF|Ordinul|Ordin|Ord\.) *(nr\. *)?[0-9][0-9.]*/[0-9]{4}"
                   r"|Codul (civil|fiscal|muncii)[^\t]{0,20}art\. *[0-9]|ISO 20022|HG [0-9]|OMFP|OMF [0-9]|OUG|Legea|art\. ?[0-9]"
                   r"|Cod(ul)? civil|Ordin(ul)? [A-Z0-9]")
DOMENII = ("legislatie.just.ro", "monitoruloficial.ro", "anaf.ro", "static.anaf.ro", "mfinante.gov.ro", "cnas.ro",
           "inspectiamuncii.ro", "iso.org", "eur-lex.europa.eu")
URL_OFICIAL = re.compile(r"https://(www\.)?(" + "|".join(re.escape(d) for d in DOMENII) + r")(/|\b)")
DATA = re.compile(r"\b[0-3][0-9]\.[01][0-9]\.20[0-9]{2}\b")
VERDICT_CIT = re.compile(r"^(DA|CORECTAT:.+|\[de confirmat\].*)$")


def chei_tsv(p):
    out = []
    for l in open(p, encoding="utf-8").read().split("\n"):
        if not l.strip() or l.startswith("#"):
            continue
        c = l.split("\t")
        out.append(c)
    return out


def norm(x):
    """Eticheta fără «…», fără ghilimele și fără ':' final, cu litere mici și FĂRĂ DIACRITICE — pentru potrivire
    (P01.T240 tranșa 16, D-240-68: «Tiparire» din cod = «Tipărire» din .tsv)."""
    x = re.sub(r"\(.*?\)", "", x or "")
    x = x.replace("…", "").replace("«", "").replace("»", "").replace("\u00a0", " ")
    x = "".join(ch for ch in unicodedata.normalize("NFD", x) if not unicodedata.combining(ch))
    return re.sub(r"\s+", " ", x).strip().strip(":").strip().lower()


def contine(a, b):
    """P01.T240 tranșa 16 (D-240-68): `a` apare în `b` ca CUVINTE ÎNTREGI (nu ca subșir: «tip» nu acoperă «emit si tiparesc»)."""
    return bool(a) and re.search(r"(?<!\w)" + re.escape(a) + r"(?!\w)", b) is not None


# Excepții EXPLICITE (ecran -> {etichetă normalizată: motiv}) de la «buton / câmp din inventar fără rând în .tsv».
EXC_BUTOANE = {
    "*": {"⧉": "puntea «Ecran nativ» (EvaPunteNativa), pusă de bază pe fiecare ecran, nu are rând propriu",
          "ajutor": "butonul «Ajutor» însuși"},
}
EXC_CAMPURI = {
    "*": {"nr. crt.": "coloana de numerotare pusă de bază (WEvaFormBase.java:1855-1862), nu e o dată a ecranului"},
}


def acoperire(inv, ecran, tsv_rows):
    """(butoane din inventar fără buton.N.nume, câmpuri / coloane din inventar fără camp.N.nume sau mențiune în camp.N.text)."""
    nume_b = [norm(c[1]) for c in tsv_rows if c[0].startswith("buton.") and c[0].endswith(".nume") and len(c) > 1]
    nume_c = [norm(c[1]) for c in tsv_rows if c[0].startswith("camp.") and c[0].endswith(".nume") and len(c) > 1]
    text_c = " ".join(norm(c[1]) for c in tsv_rows if c[0].startswith("camp.") and c[0].endswith(".text") and len(c) > 1)
    exb = {norm(k): v for k, v in list(EXC_BUTOANE.get("*", {}).items()) + list(EXC_BUTOANE.get(ecran, {}).items())}
    exc = {norm(k): v for k, v in list(EXC_CAMPURI.get("*", {}).items()) + list(EXC_CAMPURI.get(ecran, {}).items())}
    nume_b += nume_c        # o bifă (Checkbox) cu eticheta pusă prin setLabel() apare în inventar ca «buton»: i se acceptă și rândul camp.N.nume
    lipsa_b = []
    for b in inv["butoane"]:
        n = norm(b)
        if not n or n in exb:
            continue
        if not any(n == x or contine(n, x) or contine(x, n) for x in nume_b if x):
            lipsa_b.append(b)
    lipsa_c = []
    for c in inv["campuri"] + inv["coloane"]:
        n = norm(c)
        if not n or n in exc:
            continue
        if not (any(n == x or contine(n, x) or contine(x, n) for x in nume_c if x) or contine(n, text_c)):
            lipsa_c.append(c)
    return lipsa_b, lipsa_c


def verifica_inventar():
    """D7 / D-1.7-a: inventarul prinde butoanele cu Etichete.t(...) (setLabel, new Button, buton(btX, "cheie") din clase ajutătoare)."""
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    import inventar_ecrane as inv
    cl = inv.clase()
    asteptat = {"WSagaConfigAplicatieForm": "Salvez", "WDeclaratiiForm": "Descarc XML",
                "WSagaInchidereLunaForm": "Reînchidere…", "WCursuriForm": "Import BNR pe an…"}
    lipsa = 0
    for e, b in asteptat.items():
        if b not in [x.strip() for x in inv.analiza(e, cl[e], cl)["butoane"]] and not any(b in x for x in inv.analiza(e, cl[e], cl)["butoane"]):
            lipsa += 1
            print("  inventar: lipsește butonul «%s» la %s" % (b, e))
    return lipsa


def rand_tabel(tp):
    """Rândurile unui tabel de verificare: cheie -> celulele ultimului rând; plus contoarele «plauzibil» / «fără dovadă»."""
    t, pl, fd = {}, 0, 0
    for l in open(tp, encoding="utf-8").read().split("\n"):
        if not l.startswith("|"):
            continue
        p = [x.strip() for x in l.strip().strip("|").split("|")]
        if len(p) < 4 or p[0] in ("cheie", "---") or set(p[0]) <= {"-"}:
            continue
        t[p[0].strip("`")] = p
        if re.search(r"plauzibil", l, re.I):
            pl += 1
        if not p[2] or not VERDICT.match(p[3]):
            fd += 1
    return t, pl, fd


SUPL_RO_FORMAL = SUPL_EN_DIAC = 0


def suplimente():
    """(tabele, total, chei fără rând) pentru H/supliment/*.tsv față de V/supliment/*.md."""
    if not os.path.isdir(SUPL):
        return 0, 0, 0
    tab = tot = cf = 0
    global SUPL_RO_FORMAL, SUPL_EN_DIAC
    for f in sorted(os.listdir(SUPL)):
        if not f.endswith(".tsv"):
            continue
        tot += 1
        e = f[:-4]
        for c in chei_tsv(os.path.join(SUPL, f)):   # P01.T240 L2 (D-240-45): aceleași reguli de limbă ca la H/*.tsv
            if len(c) > 1 and FORMAL.search(CITAT.sub("", c[1])):
                SUPL_RO_FORMAL += 1
                print("  supliment ro formal: %s %s" % (e, c[0]))
            if len(c) > 2 and DIAC.search(CITAT.sub("", c[2])):
                SUPL_EN_DIAC += 1
                print("  supliment en diacritice: %s %s" % (e, c[0]))
        tp = os.path.join(VSUPL, e + ".md")
        if not os.path.isfile(tp):
            print("  supliment fără tabel: " + e)
            continue
        tab += 1
        t, _, _ = rand_tabel(tp)
        ch = {c[0] for c in chei_tsv(os.path.join(SUPL, f))}
        for k in sorted(ch - set(t)):
            cf += 1
            print("  supliment fără rând: %s %s" % (e, k))
        for k in sorted(set(t) - ch):
            cf += 1
            print("  supliment rând fără cheie în .tsv: %s %s" % (e, k))
    return tab, tot, cf


def aparitii_rcit():
    """[(«<E>.tsv:<rând>» sau «supliment/<E>.tsv:<rând>», potrivirea)] pe rândurile non-# — cheia e fișier:rând (CO-10)."""
    out = []
    for d, pref in ((HELP, ""), (SUPL, "supliment/")):
        if not os.path.isdir(d):
            continue
        for f in sorted(os.listdir(d)):
            if not f.endswith(".tsv"):
                continue
            for i, l in enumerate(open(os.path.join(d, f), encoding="utf-8").read().split("\n"), 1):
                if l and not l.startswith("#"):
                    out += [("%s%s:%d" % (pref, f, i), m.group(0)) for m in R_CIT.finditer(l)]
    return out


def citari():
    ap = aparitii_rcit()
    loc = sorted({a[0] for a in ap})
    randuri = {}
    if os.path.isfile(CITARI):
        for l in open(CITARI, encoding="utf-8").read().split("\n"):
            if not l.startswith("|"):
                continue
            p = [x.strip() for x in l.strip().strip("|").split("|")]
            k = p[0].strip("`") if p else ""
            if not re.fullmatch(r"(supliment/)?W[A-Za-z0-9]+\.tsv:[0-9]+", k):
                continue
            randuri.setdefault(k, []).append(p)
    fara = [a for a in ap if a[0] not in randuri]
    for a in fara:
        print("  citare fără rând în 00_CITARI_LEGALE.md: %s «%s»" % a)
    fu = fdv = 0
    for k, rs in sorted(randuri.items()):
        for p in rs:
            cel = " | ".join(p)
            if not URL_OFICIAL.search(cel):
                fu += 1
                print("  rând fără URL oficial: " + k)
            if len(p) < 7 or not DATA.search(p[4]) or not VERDICT_CIT.match(p[6]):
                fdv += 1
                print("  rând fără dată (col. 5) / verdict (col. 7): " + k)
    fara_ap = [k for k in randuri if k not in loc]
    for k in fara_ap:
        print("  rând fără apariție R-CIT în .tsv (rând mutat / citare scoasă): " + k)
    print("apariții %d · distincte %d · rânduri .tsv %d · citări fără rând %d · rânduri fără URL %d · rânduri fără dată / verdict %d · rânduri fără apariție %d"
          % (len(ap), len({a[1] for a in ap}), len(loc), len(fara), fu, fdv, len(fara_ap)))
    return 0 if not (fara or fu or fdv or fara_ap) else 1


def main():
    arg = sys.argv[1:]
    if "--citari" in arg:
        return citari()
    fara = set()
    for a in arg:
        if a.startswith("--fara-tabel"):
            fara = set(a.split("=", 1)[1].split(",")) if "=" in a else set()
    ecrane = sorted(f[:-4] for f in os.listdir(HELP) if f.endswith(".tsv"))
    tabele = chei_fara = fara_dovada = plauzibil = ro_formal = en_diac = bfr = cfr = nerez = 0
    lipsa_tabel = []
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    import inventar_ecrane as inv
    cl = inv.clase()
    for e in ecrane:
        rows = chei_tsv(os.path.join(HELP, e + ".tsv"))
        if e in cl:
            an = inv.analiza(e, cl[e], cl)
            for x in an.get("nerezolvate", []):   # P01.T240 tranșa 16 (X223): o cheie pe care inventarul n-o poate citi = NEREZOLVAT, în rc
                nerez += 1
                print("  NEREZOLVAT (cheie de etichetă fără text): %s «%s»" % (e, x))
            lb, lc = acoperire(an, e, rows)
            bfr += len(lb)
            cfr += len(lc)
            for x in lb:
                print("  buton din inventar fără rând buton.N.nume: %s «%s»" % (e, x))
            for x in lc:
                print("  câmp / coloană din inventar fără rând camp.N: %s «%s»" % (e, x))
        for c in rows:
            ro = CITAT.sub("", c[1]) if len(c) > 1 else ""
            en = CITAT.sub("", c[2]) if len(c) > 2 else ""
            if FORMAL.search(ro):
                ro_formal += 1
            if DIAC.search(en):
                en_diac += 1
        tp = os.path.join(VER, e + ".md")
        if not os.path.isfile(tp):
            if e not in fara:
                lipsa_tabel.append(e)
            continue
        tabele += 1
        t, pl, fd = rand_tabel(tp)
        plauzibil += pl
        fara_dovada += fd
        for c in rows:
            if c[0] not in t:
                chei_fara += 1
                print("  fără rând: %s %s" % (e, c[0]))
        for k in t:
            if k not in {c[0] for c in rows} and t[k][3] != "ȘTERS":   # P01.T240 L2: rândul ȘTERS = cheia scoasă din .tsv
                chei_fara += 1
                print("  rând fără cheie în .tsv: %s %s" % (e, k))
    inv_lipsa = verifica_inventar()
    total = len(ecrane) - len(fara & set(ecrane))
    for e in lipsa_tabel:
        print("  fără tabel: " + e)
    st, stot, scf = suplimente()
    print("tabele %d/%d · chei fără rând %d · rânduri fără dovadă %d · rânduri «plauzibil» %d · ro formal %d · en diacritice %d · butoane fără rând %d · câmpuri fără rând %d · inventar fără butoane %d · chei nerezolvate %d · supliment: tabele %d/%d · chei fără rând %d · ro formal %d · en diacritice %d"
          % (tabele, total, chei_fara, fara_dovada, plauzibil, ro_formal, en_diac, bfr, cfr, inv_lipsa, nerez, st, stot, scf, SUPL_RO_FORMAL, SUPL_EN_DIAC))
    return 0 if tabele == total and st == stot and not any((chei_fara, fara_dovada, plauzibil, ro_formal, en_diac, bfr, cfr, inv_lipsa, nerez, scf,
                                                            SUPL_RO_FORMAL, SUPL_EN_DIAC)) else 1


if __name__ == "__main__":
    sys.exit(main())

