#!/usr/bin/env python3
"""P01.T240 A-6 (81_) — fișa unui capitol ManualEvA pentru auditul textelor (doar citire).
Utilizare (din rădăcina worktree-ului): python3 -I <acest fișier> <ClasaForma> [...]
Tipărește: grupul (meniu), titlul capitolului, titlul ecranului (titlu() rezolvat prin etichete.tsv RO sau literal),
blocul capitolului cu numerele de linie și, pentru fiecare «X» din capitol, unde apare X ca text de interfață:
ET = valoare RO în etichete.tsv (orice etichete.tsv din P), LIT = literal Java în P (în afara ManualEvA), NEGĂSIT = nicăieri."""
import glob, os, re, sys
P = 'idempiere/plugins/com.eva.ro.contab/src/com/eva/ro/contab'
M = P + '/ajutor/ManualEvA.java'
GRUPURI = None
def etichete():
    d = {}; ro = set()
    for f in glob.glob(P + '/**/etichete*.tsv', recursive=True):
        for ln in open(f, encoding='utf-8'):
            c = ln.rstrip('\n').split('\t')
            if len(c) >= 2 and not ln.startswith('#'):
                d.setdefault(c[0], c[1]); ro.add(c[1].strip())
    return d, ro
def literali():
    s = set()
    for f in glob.glob(P + '/**/*.java', recursive=True):
        if f.endswith('ManualEvA.java'):
            continue
        for m in re.finditer(r'"((?:[^"\\]|\\.)*)"', open(f, encoding='utf-8').read()):
            s.add(m.group(1).strip())
    return s
def bara(cls):
    # numele de meniu AD_Menu ale clasei (tabelele {"Nume", "WxForm", "seq"} din EvaMetadata) → intrările barei SAGA (EvaSagaMenuDef)
    em = open(P + '/setup/EvaMetadata.java', encoding='utf-8').read()
    nume = set(re.findall(r'\{"([^"]+)",\s*"%s"' % re.escape(cls), em))
    md = open('idempiere/plugins/com.eva.ro.saga.theme/src/com/eva/ro/saga/theme/EvaSagaMenuDef.java', encoding='utf-8').read().split('\n')
    rez = []; grup = ''
    for n, l in enumerate(md, 1):
        g = re.search(r'menu\("([^"]+)"', l)
        if g: grup = g.group(1)
        for lab, tinta in re.findall(r'item\("([^"]+)",\s*"([^"]+)"', l):
            if tinta in nume:
                rez.append('%s › %s (EvaSagaMenuDef.java:%d, ținta «%s»)' % (grup, lab, n, tinta))
    if not rez:
        rez.append('— (meniul AD_Menu: %s)' % (', '.join('«%s»' % x for x in sorted(nume)) or '—'))
    return rez
def norm(x):
    return x.replace('...', '…').strip().rstrip('…').strip().lower()
def main():
    linii = open(M, encoding='utf-8').read().split('\n')
    et, ro = etichete(); lit = literali()
    ron = {norm(x) for x in ro}; litn = {norm(x) for x in lit}
    starturi = [i for i, l in enumerate(linii) if re.match(r'\s*cap\("', l)]
    for cls in sys.argv[1:]:
        gas = [i for i in starturi if re.search(r'cap\("[^"]*", *"[^"]*", *"%s"' % re.escape(cls), linii[i]) or
