        if not gas and cls == 'WEvaRegesAplicatieForm':
            reges(et, ron, litn); continue
        if not gas:
            print('=== %s: FĂRĂ CAPITOL' % cls); continue
        i = gas[0]; j = next((k for k in starturi if k > i), len(linii))
        bloc = '\n'.join(linii[i:j])
        m = re.search(r'cap\("([^"]*)",\s*"([^"]*)",\s*"([^"]*)"', bloc, re.S)
        print('=== %s · ManualEvA.java:%d-%d · meniu «%s» · titlu «%s»' % (cls, i + 1, j, m.group(1), m.group(2)))
        for b in bara(cls):
            print('    bara SAGA: %s' % b)
        f = P + '/form/%s.java' % cls
        if os.path.exists(f):
            t = re.search(r'String titlu\(\)\s*\{\s*return\s+([^;]+);', open(f, encoding='utf-8').read())
            if t:
                k = re.search(r'Etichete\.t\("([^"]+)"', t.group(1))
                print('    titlu() ecran: %s' % (('«%s» (%s)' % (et.get(k.group(1), '?'), k.group(1))) if k else t.group(1).strip()))
        for n, l in enumerate(linii[i:j], start=i + 1):
            print('%5d %s' % (n, l.rstrip()))
        lipit = re.sub(r'"\s*\+\s*"', '', bloc)   # concatenările Java «"…" + "…"» lipite înaintea căutării «…»
        for q in sorted(set(re.findall(r'«([^»]{1,80})»', lipit))):
            nq = norm(q)
            unde = 'ET' if nq in ron else ('LIT' if nq in litn else 'NEGĂSIT')
            print('    «%s» → %s' % (q, unde))
def reges(et, ron, litn):
    # capitolele paginii REGES vin din ManualReges.java (FORMA = WEvaRegesAplicatieForm), meniul «REGES»
