        bloc = '\n'.join(lin[i:j])
        m = re.search(r's\((null|"[^"]*"),\s*([^,]+),', bloc, re.S)
        qs = sorted(set(re.findall(r'«([^»]{1,80})»', re.sub(r'"\s*\+\s*"', '', bloc))))
        neg = [q for q in qs if norm(q) not in ron and norm(q) not in litn]
        print('  ManualReges.java:%d %s %s · «» %d · NEGĂSIT: %s' % (i + 1, m.group(1), m.group(2).strip(), len(qs), ' ; '.join('«%s»' % q for q in neg) or '—'))
main()

