    target=root/IDENT[iid]['path']
    cmd=[str(PY),'-X','utf8','-I','-B',str(root/'guard.py'),str(root),str(target)]+[str(x) for x in a]
    t=time.monotonic()
    try:
        cp=subprocess.run(cmd,cwd=root,capture_output=True,text=True,encoding='utf8',timeout=60)
        rc=cp.returncode; out=cp.stdout; err=cp.stderr; timeout=False
    except subprocess.TimeoutExpired as e:
        rc=None; out=str(e.stdout); err=str(e.stderr); timeout=True
    elapsed=round(time.monotonic()-t,4)
    after=inv(root); changed=[p for p,h in inputs.items() if after.get(p)!=h]; created=[p for p in after if p not in inputs]
    checks={'exitcode':rc==expect_rc,'expected_stdout':all(x in out for x in contains),'excluded_stdout':all(x not in out for x in absent),'input_unchanged':not changed,'no_timeout':not timeout}
    trace=json.loads((root/'guard_trace.json').read_text()) if (root/'guard_trace.json').is_file() else {'events':[{'missing':True}]}
    checks['no_denied_product_operations']=not trace['events']
    extra=post(root,out) if post else {}
    checks.update(extra.get('checks',{}))
    result={'case':cid,'instrument':iid,'description':description,'source_oid':IDENT[iid]['git_object'],'command':cmd,'cwd':str(root),'exitcode':rc,'expected_exitcode':expect_rc,'oracle_matches':all(checks.values()),'checks':checks,'elapsed_s':elapsed,'stdout':out,'stderr':err,'changed_inputs':changed,'created_files':created,'input_count':len(inputs),'input_hashes':inputs,'output_hashes':{p:after[p] for p in created},'guard':trace,'observation':extra.get('observation'),'semantics':'Oracle checks observed behavior, including defect witnesses; not a product PASS.'}
    caseout=O/'cases'/cid; caseout.mkdir(parents=True)
    js(caseout/'result.json',result); write(caseout/'stdout.txt',out); write(caseout/'stderr.txt',err)
    with zipfile.ZipFile(caseout/'synthetic_repository.zip','w',zipfile.ZIP_DEFLATED) as z:
